      /** Format: date-time */
      closed_at?: string;
      diagnoses?: string;
      plan?: string;
      /** @description A number rather than "in three months", because the outreach engine reads it. */
      next_review_days?: number;
      /** Format: date-time */
      next_review_on?: string;
      /** @description How many times this visit has been reopened. Three is worth somebody looking. */
      reopened_count: number;
