      reason: string;
      name_en?: string;
      name_bn?: string;
      /** @enum {string} */
      sex?: 'female' | 'male' | 'other';
      /** Format: date */
      birth_date?: string;
      /** @enum {string} */
      dob_precision?: 'day' | 'month' | 'year';
      dob_source?: string;
      phone_primary?: string;
      phone_secondary?: string;
      division?: string;
      district?: string;
      upazila?: string;
      address_line?: string;
      postcode?: string;
